<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { platformApi } from '../api'; import PageHeader from '../components/PageHeader.vue'; import ResourceState from '../components/ResourceState.vue'; import type { DeviceTemplateDocument } from '../types'
const templates = ref<DeviceTemplateDocument[]>([]); const loading = ref(true); const error = ref(''); const query = ref('')
async function load() { loading.value = true; try { templates.value = await platformApi.templates(query.value) } catch (cause) { error.value = cause instanceof Error ? cause.message : String(cause) } finally { loading.value = false } }
onMounted(load)
</script>
<template><main class="content"><PageHeader eyebrow="Model" title="Device templates" description="Create immutable logical device definitions, then attach explicit protocol mapping profiles."><input v-model="query" class="search-input" placeholder="Search templates" @keyup.enter="load" /><button @click="load">Search</button></PageHeader><ResourceState :loading="loading" :error="error" :empty="templates.length === 0" empty-text="No templates yet. Create the first reusable device definition."><div class="card-grid"><article v-for="item in templates" :key="`${item.id}@${item.version}`" class="entity-card"><div class="entity-card-head"><div><span class="type-badge">{{ item.deviceType }}</span><h2>{{ item.displayName }}</h2></div><span class="version-chip">v{{ item.version }}</span></div><p>{{ item.description }}</p><div class="tag-row"><span v-for="tag in item.tags" :key="tag">{{ tag }}</span></div><small>{{ item.dataPoints.length }} datapoints · {{ item.commands.length }} commands</small></article></div></ResourceState></main></template>
